// Command proc-tunnel was generated by new_probe.py from templates/process.go.tmpl:
// it measures the processes whose WMI name matches cloudflared%, summed, and
// prints proc_tunnel_cpu_pct (their share of the whole machine) and
// proc_tunnel_ram_mb (private working set), every PROBE_INTERVAL_MS
// milliseconds. Regenerate it rather than editing it.
package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"runtime"
	"strconv"
	"time"

	"github.com/yusufpapurcu/wmi"
)

const (
	match  = "cloudflared%"
	metric = "tunnel"
)

type process struct {
	PercentProcessorTime uint64 // percent of one logical processor
	WorkingSetPrivate    uint64 // bytes
}

type observation struct {
	TS     string  `json:"ts"`
	Metric string  `json:"metric"`
	Value  float64 `json:"value"`
	Unit   string  `json:"unit"`
}

var errStdout = errors.New("stdout")

func main() {
	every := time.Second
	if ms, err := strconv.Atoi(os.Getenv("PROBE_INTERVAL_MS")); err == nil && ms > 0 {
		every = time.Duration(ms) * time.Millisecond
	}
	enc := json.NewEncoder(os.Stdout)
	tick := time.NewTicker(every)
	for ; ; <-tick.C {
		if err := sample(enc); err != nil {
			fmt.Fprintln(os.Stderr, err)
			if errors.Is(err, errStdout) {
				os.Exit(1)
			}
		}
	}
}

func sample(enc *json.Encoder) error {
	var procs []process
	q := "SELECT PercentProcessorTime, WorkingSetPrivate FROM Win32_PerfFormattedData_PerfProc_Process WHERE Name LIKE '" + match + "'"
	if err := wmi.Query(q, &procs); err != nil {
		return fmt.Errorf("Win32_PerfFormattedData_PerfProc_Process: %w", err)
	}
	var cpu, ram float64
	for _, p := range procs {
		cpu += float64(p.PercentProcessorTime)
		ram += float64(p.WorkingSetPrivate)
	}
	ts := time.Now().UTC().Format("2006-01-02T15:04:05.000000Z07:00")
	for _, o := range []observation{
		{ts, "proc_" + metric + "_cpu_pct", cpu / float64(runtime.NumCPU()), "%"},
		{ts, "proc_" + metric + "_ram_mb", ram / (1 << 20), "MB"},
		{ts, "proc_" + metric + "_count", float64(len(procs)), "count"},
	} {
		if err := enc.Encode(o); err != nil {
			return fmt.Errorf("%w: %v", errStdout, err)
		}
	}
	return nil
}
